// Loads the trusted Red Ivy episode data (generated by scripts/build-red-ivy.mjs) for the local AI dev server.
// The Vercel function gets the same data inlined by scripts/export-github-static.py.
import { readFileSync, readdirSync } from 'node:fs';
export function loadRedIvy(dir) {
  const episodes = {};
  for (const f of readdirSync(dir).filter(f => /^ep\d+\.json$/.test(f))) {
    const ep = JSON.parse(readFileSync(new URL(f, dir), 'utf8'));
    episodes[ep.episode_id] = ep;
  }
  return { episodes };
}
